import { Popover } from '@absoluteui/components/popover';
import { Button } from '@absoluteui/components/button';
import { Checkbox } from '@absoluteui/components/checkbox';

const trigger = document.createElement('button');
trigger.type = 'button';
trigger.textContent = 'Filters';
Button.enhance(trigger);
document.body.append(trigger);
const form = document.createElement('div');
const onlyActive = document.createElement('div');
form.append(onlyActive);
Checkbox.create(onlyActive, { label: 'Only active' });
Popover.create(trigger, { title: 'Filters', content: form, showCloseButton: true });

import { Popover, type PopoverCloseDetail } from '@absoluteui/components/popover';
import { Button } from '@absoluteui/components/button';
import { Textarea } from '@absoluteui/components/textarea';

const trigger = document.createElement('button');
trigger.type = 'button';
trigger.textContent = 'Add note';
Button.enhance(trigger);
document.body.append(trigger);
const noteHost = document.createElement('div');
const note = Textarea.create(noteHost, { label: 'Note' }).textarea;
const popover = Popover.create(trigger, { label: 'Add note', content: noteHost, placement: 'right-start' });
popover.element.addEventListener('aui-cancel', (event) => {
  const { reason } = (event as CustomEvent<PopoverCloseDetail>).detail;
  if (reason === 'outside-pointer' && note.value !== '') event.preventDefault();
});
